  "implementation": "import math

def solve(case):
    # Validate matrix presence
    matrix = case.get('matrix')
    if not matrix or not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError("Missing or empty matrix")
    # Validate rectangular
    n_rows = len(matrix)
    n_cols = len(matrix[0]) if n_rows > 0 else 0
    for row in matrix:
        if not isinstance(row, list) or len(row) != n_cols:
            raise ValueError("Matrix rows must be lists of equal length")
        for val in row:
            if not isinstance(val, (int, float)):
                raise ValueError("Matrix entries must be numeric")
    # Compute document frequency per column
    df = [0] * n_cols
    for row in matrix:
        for j, val in enumerate(row):
            if val != 0:
                df[j] += 1
    # Compute IDF: log(1 + n_rows / (1 + df))
    idf = [math.log(1 + n_rows / (1 + d)) for d in df]
    # Build weighted matrix (multiply each entry by its feature idf)
    weighted_matrix = []
    for row in matrix:
        weighted_row = [round(val * idf[j], 6) for j, val in enumerate(row)]
        weighted_matrix.append(weighted_row)
    # Compute row degree (sum of weighted row)
    row_degree = [round(sum(row), 6) for row in weighted_matrix]
    # Round idf as well
    idf_rounded = [round(x, 6) for x in idf]
    return {
        'idf': idf_rounded,
        'row_degree': row_degree,
        'weighted_matrix': weighted_matrix
    }
